package next.consumer
import next.probes.*
fun main() {
    check(inclusiveCount(1, 3) == 3)
    check(descendingCount(3, 1) == 3)
    check(steppedSum(1, 5, 2) == 9)
    check(arraySum(intArrayOf(1, 2)) == 3)
    check(stringSum("ab") == 195)
    check(listSum(listOf("a", "bc")) == 3)
    check(arrayIndices(intArrayOf(8, 4, -2)) == 0)
    check(doWhileSum(3) == 4)
    check(floatAdd(1f, 2f) == 3f)
    check(floatLt(1f, 2f))
    check(floatToInt(3.9f) == 3)
    check(compoundInt(7) == 0)
    check(decrement(5) == 533)
    check(identical(null, null))
    check(equalStrings("x", "x"))
    check(stringTest("x"))
    check(checkedString("x") == "x")
    check(safeString(3) == null)
    check(smartEarly("abcd") == 4)
    check(whenType("abc") == 3)
    check((3 bump 4) == 7)
    check((InfixBox(2) combine 3) == 5)
    check(iterableSum(listOf("ab")) == 2)
    check(nullableLongIterableSum(listOf(3L, null, -1L)) == 2L)
    check(customIterableSum(next.support.Words()) == 3)
    check("prefix".removePrefix("pre") == "source")
    println("Kotlin consumer: 26 checks")
}
